   79  pub fn decode_pinned(bytes: &[u8]) -> Result<Layers, String> {
   80      pinned().verify(bytes)?;
   81      Layers::decode(bytes)
   82  }
   83  
   84  /// The pinned layers in `cache`, downloaded from [`KIT_ORIGIN`] when
